begin;
update nexora.modules set description='Use JavaScript para modelar estado, regras e interação no navegador, trabalhando com DOM, eventos, formulários, persistência e APIs.' where course_id=(select id from nexora.courses where slug='programador-master') and position=4;
update nexora.lessons set objective='Explicar onde JavaScript executa no navegador e usar a linguagem para transformar estado, eventos e dados em comportamento observável.',estimated_minutes=30,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A página tem HTML e CSS corretos, mas nenhum botão reage e nenhum dado muda. É o momento em que JavaScript deixa de ser ''mais uma linguagem'' e passa a controlar comportamento."},{"type":"concept","title":"JavaScript e o papel da linguagem na Web","body":"JavaScript é a linguagem que normalmente adiciona comportamento dinâmico às páginas. Ele executa no navegador, manipula dados em memória, reage a eventos, acessa APIs da Web e altera o DOM. HTML define estrutura, CSS define apresentação e JavaScript coordena interação e lógica. Separar esses papéis ajuda a decidir onde cada regra deve viver e evita colocar lógica de negócio em atributos ou estilos."},{"type":"mechanics","title":"Como aplicar","items":["Use JavaScript para comportamento e transformação de dados.","Mantenha HTML como estrutura e CSS como apresentação.","Observe entradas, estado e saída ao depurar.","Evite misturar regras em handlers gigantes."]},{"type":"example","title":"Exemplo","body":"const botao=document.querySelector(''#acao'');\\nbotao.addEventListener(''click'',()=>{\\n  console.log(''Clique recebido'');\\n});","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Tratar JavaScript como sequência de comandos soltos. Mesmo scripts pequenos precisam de estado, responsabilidade e fluxo claros."},{"type":"guided","question":"Qual papel JavaScript normalmente desempenha em uma página Web?","options":["Comportamento e lógica.","Apenas tipografia.","Apenas estrutura semântica."],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Explicar onde JavaScript executa no navegador e usar a linguagem para transformar estado, eventos e dados em comportamento observável.","Use JavaScript para comportamento e transformação de dados.","Mantenha HTML como estrutura e CSS como apresentação.","Observe entradas, estado e saída ao depurar."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='JavaScript e o papel da linguagem na Web';
update nexora.lessons set objective='Declarar valores com const e let, reconhecer tipos primitivos e evitar coerções implícitas que produzem resultados inesperados.',estimated_minutes=36,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Um preço vindo de input é string e a soma com outro número gera ''10020'' em vez de 120. O erro está no tipo, não na fórmula."},{"type":"concept","title":"Variáveis, tipos e coerção","body":"JavaScript possui tipagem dinâmica: valores têm tipos, mas variáveis não ficam presas a um tipo declarado. Strings, numbers, booleans, null, undefined, bigint e symbol são primitivos. Coerção pode converter valores automaticamente, especialmente com + e comparações frouxas. Em código previsível, declare com const quando a referência não muda, let quando muda e converta entradas explicitamente antes de calcular."},{"type":"mechanics","title":"Como aplicar","items":["Prefira const por padrão.","Converta input com Number ou parse apropriado.","Use === em vez de == na maioria dos casos.","Inspecione typeof ao investigar dados inesperados."]},{"type":"example","title":"Exemplo","body":"const preco=Number(''100'');\\nconst frete=20;\\nconsole.log(preco+frete); // 120","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Assumir que todo valor digitado em input já é number. No DOM, valores de campos chegam como texto."},{"type":"guided","question":"Qual comparação evita coerção implícita entre tipos?","options":["===","==","="],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Declarar valores com const e let, reconhecer tipos primitivos e evitar coerções implícitas que produzem resultados inesperados.","Prefira const por padrão.","Converta input com Number ou parse apropriado.","Use === em vez de == na maioria dos casos."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Variáveis, tipos e coerção';
update nexora.lessons set objective='Construir expressões aritméticas, relacionais e lógicas e testar fronteiras para garantir que a regra represente o requisito.',estimated_minutes=36,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A regra diz ''frete grátis a partir de 300'', mas o código usa > 300 e exclui exatamente 300."},{"type":"concept","title":"Operadores e expressões em JavaScript","body":"Operadores formam expressões que produzem valores. Aritméticos calculam, relacionais comparam e lógicos combinam condições. A maior fonte de erro não é a sintaxe, mas a tradução imprecisa da regra. Fronteiras como maior que versus maior ou igual precisam ser testadas com casos imediatamente abaixo, no limite e acima."},{"type":"mechanics","title":"Como aplicar","items":["Escreva a regra em linguagem natural antes da expressão.","Teste limites explicitamente.","Use parênteses quando melhorarem leitura.","Evite expressões longas demais em uma única linha."]},{"type":"example","title":"Exemplo","body":"const freteGratis = total >= 300 && clienteAtivo;\\nconsole.log(freteGratis);","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Confiar em precedência implícita quando a expressão mistura &&, || e comparações. Se a intenção não está evidente, extraia variáveis."},{"type":"guided","question":"Para ''a partir de 300'', qual operador preserva a fronteira?","options":[">=",">","=="],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Construir expressões aritméticas, relacionais e lógicas e testar fronteiras para garantir que a regra represente o requisito.","Escreva a regra em linguagem natural antes da expressão.","Teste limites explicitamente.","Use parênteses quando melhorarem leitura."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Operadores e expressões em JavaScript';
update nexora.lessons set objective='Controlar fluxo com if/else e laços escolhendo condições de entrada e parada que não produzam ramos inacessíveis ou loops infinitos.',estimated_minutes=40,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Uma lista de pedidos precisa classificar cada total e somar apenas aprovados. Há decisão por item e repetição sobre a coleção."},{"type":"concept","title":"Condições e repetição","body":"Condições escolhem caminhos e laços repetem trabalho. if/else representa decisões; for, for...of e while atendem padrões diferentes de repetição. Um laço deve deixar clara a condição de parada. Quando decisão e repetição aparecem juntas, primeiro defina a regra por item; depois aplique a regra à coleção. Isso simplifica testes e evita blocos profundamente aninhados."},{"type":"mechanics","title":"Como aplicar","items":["Defina condições mutuamente compreensíveis.","Escolha for...of para percorrer valores de coleção.","Use while quando a repetição depende de condição dinâmica.","Teste casos vazios e limites."]},{"type":"example","title":"Exemplo","body":"let aprovados=0;\\nfor(const pedido of pedidos){\\n  if(pedido.total>=100) aprovados++;\\n}","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Alterar a variável de controle de um while em lugar que nem sempre executa, criando loop infinito em alguns ramos."},{"type":"guided","question":"Qual laço é direto para percorrer valores de um array?","options":["for...of","switch","try"],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Controlar fluxo com if/else e laços escolhendo condições de entrada e parada que não produzam ramos inacessíveis ou loops infinitos.","Defina condições mutuamente compreensíveis.","Escolha for...of para percorrer valores de coleção.","Use while quando a repetição depende de condição dinâmica."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Condições e repetição';
update nexora.lessons set objective='Extrair responsabilidades em funções com parâmetros e retorno, explicando escopo e evitando dependência excessiva de variáveis globais.',estimated_minutes=42,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A mesma regra de desconto aparece em três handlers e cada versão já começou a divergir."},{"type":"concept","title":"Funções, escopo e retorno","body":"Funções encapsulam comportamento. Parâmetros tornam entradas explícitas; return produz uma saída; escopo determina onde nomes podem ser acessados. Funções pequenas e determinísticas são mais fáceis de testar e reutilizar. Quando uma função depende de variáveis globais ocultas, fica difícil prever seu resultado. Prefira receber o necessário e devolver o resultado."},{"type":"mechanics","title":"Como aplicar","items":["Dê à função uma responsabilidade clara.","Receba dados por parâmetros.","Retorne resultados em vez de alterar estado global sem necessidade.","Evite funções longas que fazem validação, cálculo, DOM e rede juntas."]},{"type":"example","title":"Exemplo","body":"function calcularDesconto(total,taxa){\\n  return total*taxa;\\n}\\nconsole.log(calcularDesconto(200,.1));","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Criar funções que só funcionam porque leem várias variáveis externas. Isso aumenta acoplamento e dificulta testes."},{"type":"guided","question":"Qual prática torna uma função mais previsível?","options":["Entradas por parâmetros e saída por return.","Dependência de várias globais.","Alterar DOM e rede sempre."],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Extrair responsabilidades em funções com parâmetros e retorno, explicando escopo e evitando dependência excessiva de variáveis globais.","Dê à função uma responsabilidade clara.","Receba dados por parâmetros.","Retorne resultados em vez de alterar estado global sem necessidade."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Funções, escopo e retorno';
update nexora.lessons set objective='Modelar coleções e registros com arrays e objetos e acessar dados usando estrutura coerente com o problema.',estimated_minutes=42,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Você precisa representar vários cursos, cada um com nome, preço e status. Uma sequência de variáveis separadas não escala."},{"type":"concept","title":"Arrays e objetos","body":"Arrays representam coleções ordenadas; objetos agrupam propriedades relacionadas de uma entidade. Em aplicações, é comum ter arrays de objetos. Escolher estrutura adequada reduz variáveis desconectadas e permite operações de busca, filtro e transformação. A modelagem deve refletir o domínio: nomes de propriedades precisam ser claros e o formato deve ser consistente entre itens."},{"type":"mechanics","title":"Como aplicar","items":["Use array para coleção de itens semelhantes.","Use objeto para propriedades relacionadas de um item.","Mantenha chaves consistentes entre registros.","Evite índices mágicos quando um objeto expressa melhor o significado."]},{"type":"example","title":"Exemplo","body":"const cursos=[\\n {id:1,nome:''JavaScript'',ativo:true},\\n {id:2,nome:''Python'',ativo:false}\\n];","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Representar entidade como array posicional, por exemplo [''JS'',120,true], quando ninguém sabe o que cada posição significa."},{"type":"guided","question":"Qual estrutura representa melhor uma coleção de cursos com várias propriedades?","options":["Array de objetos.","Uma string gigante.","Um booleano."],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Modelar coleções e registros com arrays e objetos e acessar dados usando estrutura coerente com o problema.","Use array para coleção de itens semelhantes.","Use objeto para propriedades relacionadas de um item.","Mantenha chaves consistentes entre registros."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Arrays e objetos';
update nexora.lessons set objective='Usar map, filter, find, some e reduce conforme a intenção, evitando loops manuais quando a operação de coleção é expressa melhor por um método.',estimated_minutes=44,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Você precisa obter só os produtos ativos, transformar nomes e calcular total. Um único for faz tudo e fica difícil de ler."},{"type":"concept","title":"Métodos de coleção","body":"Métodos de array expressam intenções comuns. map transforma cada item; filter seleciona; find encontra o primeiro; some/every verificam condição; reduce acumula. Escolher o método certo melhora leitura porque o código comunica o que pretende fazer. Não é obrigatório usar encadeamentos longos: etapas nomeadas podem ser mais claras e fáceis de depurar."},{"type":"mechanics","title":"Como aplicar","items":["Use filter para subconjuntos.","Use map quando a saída tem um item correspondente por entrada.","Use find para primeira ocorrência.","Nomeie etapas quando o encadeamento fica difícil de entender."]},{"type":"example","title":"Exemplo","body":"const ativos=produtos.filter(p=>p.ativo);\\nconst nomes=ativos.map(p=>p.nome);","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Usar map apenas pelos efeitos colaterais e ignorar o array retornado. Nesse caso, forEach ou outro desenho pode ser mais coerente."},{"type":"guided","question":"Qual método retorna apenas itens que atendem a uma condição?","options":["filter","map","join"],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Usar map, filter, find, some e reduce conforme a intenção, evitando loops manuais quando a operação de coleção é expressa melhor por um método.","Use filter para subconjuntos.","Use map quando a saída tem um item correspondente por entrada.","Use find para primeira ocorrência."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Métodos de coleção';
update nexora.lessons set objective='Selecionar elementos do DOM e atualizar conteúdo, atributos e classes mantendo separação entre estado e renderização.',estimated_minutes=46,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A aplicação possui um contador no dado e outro valor diferente no texto da tela. O DOM virou fonte de verdade sem perceber."},{"type":"concept","title":"DOM: selecionar e alterar a página","body":"O DOM é a representação da página que JavaScript pode consultar e alterar. querySelector localiza elementos; textContent altera texto; classList gerencia classes; atributos podem ser lidos e escritos. Em interfaces maiores, é saudável tratar os dados da aplicação como estado e renderizar o DOM a partir deles, em vez de extrair regras do texto da tela."},{"type":"mechanics","title":"Como aplicar","items":["Use seletores estáveis e específicos ao componente.","Prefira textContent para texto simples.","Use classes para estados visuais.","Evite espalhar atualizações do mesmo elemento por muitos lugares."]},{"type":"example","title":"Exemplo","body":"const totalEl=document.querySelector(''[data-total]'');\\nfunction render(total){\\n  totalEl.textContent=total.toLocaleString(''pt-BR'');\\n}","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Usar innerHTML com dados não confiáveis sem necessidade. Além de acoplamento, isso pode abrir risco de injeção."},{"type":"guided","question":"Qual propriedade é adequada para inserir texto simples sem interpretar HTML?","options":["textContent","innerHTML sempre","style"],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Selecionar elementos do DOM e atualizar conteúdo, atributos e classes mantendo separação entre estado e renderização.","Use seletores estáveis e específicos ao componente.","Prefira textContent para texto simples.","Use classes para estados visuais."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='DOM: selecionar e alterar a página';
update nexora.lessons set objective='Registrar listeners, interpretar o objeto de evento e coordenar ações do usuário sem duplicar handlers ou misturar responsabilidades.',estimated_minutes=44,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"Cada render adiciona um novo click listener; depois de alguns minutos, um clique executa a mesma ação várias vezes."},{"type":"concept","title":"Eventos e interação do usuário","body":"Eventos representam acontecimentos como clique, input, submit e teclado. addEventListener conecta uma função a um evento. O objeto event traz alvo e contexto. A arquitetura deve definir quando listeners são registrados e evitar recriá-los de forma descontrolada. Delegação de eventos pode ser útil para listas dinâmicas, mas exige entender bubbling."},{"type":"mechanics","title":"Como aplicar","items":["Registre listeners em ponto previsível do ciclo da tela.","Use submit no formulário em vez de click apenas no botão.","Conheça preventDefault e bubbling.","Remova listeners quando componentes realmente precisam ser desmontados."]},{"type":"example","title":"Exemplo","body":"form.addEventListener(''submit'',event=>{\\n  event.preventDefault();\\n  salvar();\\n});","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Colocar lógica de formulário somente no click do botão. Enter e outras formas de submit podem ignorar esse caminho."},{"type":"guided","question":"Qual evento representa melhor o envio de um formulário?","options":["submit","mouseover","scroll"],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Registrar listeners, interpretar o objeto de evento e coordenar ações do usuário sem duplicar handlers ou misturar responsabilidades.","Registre listeners em ponto previsível do ciclo da tela.","Use submit no formulário em vez de click apenas no botão.","Conheça preventDefault e bubbling."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Eventos e interação do usuário';
update nexora.lessons set objective='Validar dados no cliente com regras explícitas, normalização e mensagens úteis, sem confundir validação de interface com segurança do servidor.',estimated_minutes=46,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O formulário bloqueia e-mail inválido no navegador, mas a API aceita qualquer payload enviado diretamente."},{"type":"concept","title":"Formulários e validação","body":"Validação no cliente melhora experiência, mas não substitui validação no servidor. No frontend, normalize entradas, verifique campos obrigatórios, formatos e relações entre valores, e mostre mensagens próximas ao problema. A regra deve trabalhar com dados, não com aparência. O backend precisa repetir as garantias relevantes porque o cliente pode ser contornado."},{"type":"mechanics","title":"Como aplicar","items":["Normalize trim e conversões antes de validar.","Associe mensagens ao campo correspondente.","Valide relações, como confirmação de senha ou intervalos.","Repita validações críticas no servidor."]},{"type":"example","title":"Exemplo","body":"const email=form.email.value.trim();\\nif(!email.includes(''@'')){\\n  mostrarErro(''Informe um e-mail válido'');\\n}","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Desabilitar o botão e considerar isso segurança. Uma requisição manual pode ignorar completamente a interface."},{"type":"guided","question":"Por que validação no cliente não basta para segurança?","options":["Porque o cliente pode ser contornado.","Porque JavaScript não lê strings.","Porque HTML não tem formulários."],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Validar dados no cliente com regras explícitas, normalização e mensagens úteis, sem confundir validação de interface com segurança do servidor.","Normalize trim e conversões antes de validar.","Associe mensagens ao campo correspondente.","Valide relações, como confirmação de senha ou intervalos."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Formulários e validação';
update nexora.lessons set objective='Persistir preferências e dados simples no navegador com localStorage, serializando JSON e reconhecendo limites de segurança e sincronização.',estimated_minutes=38,lab_type='javascript',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O tema escolhido desaparece ao recarregar. Você quer persistir a preferência, mas não precisa de banco remoto."},{"type":"concept","title":"LocalStorage e estado simples","body":"localStorage guarda pares chave-valor como texto no navegador. Objetos precisam ser serializados com JSON.stringify e lidos com JSON.parse. É útil para preferências, rascunhos ou estado não sensível. Não deve armazenar segredos ou ser tratado como banco confiável: usuários podem editar dados e múltiplos dispositivos não sincronizam automaticamente."},{"type":"mechanics","title":"Como aplicar","items":["Defina chaves com namespace do projeto.","Serialize objetos explicitamente.","Trate ausência ou JSON inválido.","Não armazene senhas, tokens sensíveis ou dados que exigem integridade."]},{"type":"example","title":"Exemplo","body":"localStorage.setItem(''app:tema'',''dark'');\\nconst tema=localStorage.getItem(''app:tema'') ?? ''light'';","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Confiar em localStorage como fonte de autorização. O usuário controla esse armazenamento."},{"type":"guided","question":"Como objetos são normalmente armazenados em localStorage?","options":["Serializados como JSON.","Como funções executáveis.","Como banco SQL."],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Persistir preferências e dados simples no navegador com localStorage, serializando JSON e reconhecendo limites de segurança e sincronização.","Defina chaves com namespace do projeto.","Serialize objetos explicitamente.","Trate ausência ou JSON inválido."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='LocalStorage e estado simples';
update nexora.lessons set objective='Ler e produzir JSON e explicar a estrutura básica de uma requisição/resposta HTTP com método, URL, headers, status e corpo.',estimated_minutes=42,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O frontend envia um objeto JavaScript, mas a API espera JSON e responde 400. É preciso entender representação e protocolo."},{"type":"concept","title":"JSON e requisições HTTP","body":"JSON é um formato textual de dados; HTTP é o protocolo que transporta requisições e respostas. Uma requisição possui método, URL, headers e possivelmente corpo. A resposta traz status, headers e corpo. Content-Type comunica o formato. JSON.stringify transforma valor JavaScript em texto JSON; response.json() interpreta um corpo JSON recebido."},{"type":"mechanics","title":"Como aplicar","items":["Diferencie objeto JavaScript de texto JSON.","Use Content-Type adequado ao enviar JSON.","Leia status antes de assumir sucesso.","Não tente interpretar como JSON uma resposta que não garante esse formato."]},{"type":"example","title":"Exemplo","body":"const body=JSON.stringify({nome:''Mouse'',preco:120});\\n// POST /api/produtos com Content-Type: application/json","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Assumir que toda resposta HTTP 200 contém o formato esperado. O contrato também precisa ser validado."},{"type":"guided","question":"Qual header informa que o corpo enviado é JSON?","options":["Content-Type: application/json","Accept-Language","Cache-Control: no-store sempre"],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Ler e produzir JSON e explicar a estrutura básica de uma requisição/resposta HTTP com método, URL, headers, status e corpo.","Diferencie objeto JavaScript de texto JSON.","Use Content-Type adequado ao enviar JSON.","Leia status antes de assumir sucesso."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='JSON e requisições HTTP';
update nexora.lessons set objective='Consumir APIs com fetch tratando status, falhas de rede, parsing e estados de loading/erro/sucesso.',estimated_minutes=48,lab_type='api',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"A aplicação chama fetch e tenta ler JSON mesmo quando o servidor responde 500, gerando um segundo erro que esconde o primeiro."},{"type":"concept","title":"Fetch e consumo de APIs","body":"fetch resolve a Promise mesmo para muitos status HTTP de erro; por isso response.ok precisa ser verificado. Falhas de rede podem rejeitar. Uma integração robusta modela pelo menos loading, sucesso e erro e valida os dados recebidos antes de renderizar. O objetivo não é apenas ''pegar dados'', mas tornar falhas diagnósticas e recuperáveis."},{"type":"mechanics","title":"Como aplicar","items":["Use try/catch para falhas de rede e parsing.","Verifique response.ok.","Valide estrutura mínima do payload.","Mostre estado de carregamento e mensagem de erro útil."]},{"type":"example","title":"Exemplo","body":"async function carregar(){\\n const r=await fetch(''/api/produtos'');\\n if(!r.ok) throw new Error(`HTTP ${r.status}`);\\n const data=await r.json();\\n return data;\\n}","language":"javascript"},{"type":"mistake","title":"Erro comum","body":"Chamar response.json() e renderizar sem verificar status ou formato. Isso cria erros encadeados difíceis de diagnosticar."},{"type":"guided","question":"fetch rejeita automaticamente em toda resposta 404/500?","options":["Não; é preciso verificar response.ok/status.","Sim, sempre.","Somente em localhost."],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Consumir APIs com fetch tratando status, falhas de rede, parsing e estados de loading/erro/sucesso.","Use try/catch para falhas de rede e parsing.","Verifique response.ok.","Valide estrutura mínima do payload."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Fetch e consumo de APIs';
update nexora.lessons set objective='Integrar estado, DOM, eventos, validação, persistência e consumo de API em uma aplicação web interativa publicável.',estimated_minutes=65,lab_type='project',lab_config='{}'::jsonb,content='[{"type":"story","title":"Cenário","body":"O projeto final precisa ir além de uma página estática: o usuário deve interagir, os dados precisam mudar e os estados de erro precisam ser tratados."},{"type":"concept","title":"Projeto: aplicação web interativa","body":"Uma aplicação web interativa conecta dados, regras e interface. A qualidade aparece quando o estado é previsível, eventos têm responsabilidade clara, validações protegem a experiência, integrações tratam falhas e o usuário entende o que está acontecendo. O projeto deve ser pequeno o suficiente para ser concluído, mas completo o bastante para demonstrar fluxo real."},{"type":"mechanics","title":"Como aplicar","items":["Defina um fluxo principal antes de adicionar recursos extras.","Modele estado em uma estrutura clara.","Separe funções de dados, renderização e eventos.","Teste vazio, erro, sucesso e recarregamento."]},{"type":"example","title":"Exemplo","body":"Exemplo de escopo: catálogo consumido de API + busca/filtro + favoritos persistidos + formulário validado + estados de loading e erro."},{"type":"mistake","title":"Erro comum","body":"Adicionar funcionalidades até perder o fluxo principal. Projeto de portfólio precisa ser demonstrável e confiável, não apenas grande."},{"type":"guided","question":"Qual critério pesa mais em um projeto interativo?","options":["Fluxo principal funcionando e testado.","Quantidade máxima de bibliotecas.","Número de arquivos."],"answer":0,"hint":"Escolha a alternativa que mantém o comportamento previsível.","feedback":"Correto. Você aplicou a regra da aula.","feedback_incorrect":"Revise o conceito e teste o exemplo."},{"type":"recap","items":["Integrar estado, DOM, eventos, validação, persistência e consumo de API em uma aplicação web interativa publicável.","Defina um fluxo principal antes de adicionar recursos extras.","Modele estado em uma estrutura clara.","Separe funções de dados, renderização e eventos."]}]'::jsonb,updated_at=now() where module_id=(select id from nexora.modules where course_id=(select id from nexora.courses where slug='programador-master') and position=4) and title='Projeto: aplicação web interativa';

